CREATE OR REPLACE FUNCTION public.admin_party_units_page(_party uuid,_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ WITH ids AS (SELECT cu.unit_id FROM public.contract_units cu JOIN public.contracts c ON c.id=cu.contract_id WHERE c.party_id=_party UNION SELECT bu.unit_id FROM public.booking_units bu JOIN public.bookings b ON b.id=bu.booking_id WHERE b.party_id=_party UNION SELECT t.unit_id FROM public.tenants t WHERE t.party_id=_party AND t.archived_at IS NULL UNION SELECT au.unit_id FROM public.tenant_account_units au JOIN public.tenant_accounts a ON a.id=au.tenant_account_id WHERE a.party_id=_party AND a.archived_at IS NULL), filtered AS (SELECT u.id,u.unit_number,u.building_number FROM public.units u JOIN ids ON ids.unit_id=u.id WHERE NOT u.is_test), paged AS(SELECT * FROM filtered ORDER BY building_number,unit_number,id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(paged)) FROM paged),'[]'::jsonb),'count',(SELECT count(*) FROM filtered)); $$;
REVOKE ALL ON FUNCTION public.admin_party_units_page(uuid,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_party_units_page(uuid,integer,integer) TO authenticated;
SELECT to_regprocedure('public.admin_party_units_page(uuid,integer,integer)') IS NOT NULL AS party_units_ready;